package com.nivor.ai;import com.nivor.common.entity.AuditedEntity;import jakarta.persistence.*;
@Entity @Table(name="ai_messages",indexes=@Index(name="idx_ai_message_conversation",columnList="conversation_id,created_at"))public class AiMessage extends AuditedEntity{@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="conversation_id",nullable=false)private AiConversation conversation;@Enumerated(EnumType.STRING)@Column(nullable=false,length=12)private AiMessageRole role;@Column(nullable=false,columnDefinition="TEXT")private String content;protected AiMessage(){}public AiConversation getConversation(){return conversation;}public void setConversation(AiConversation v){conversation=v;}public AiMessageRole getRole(){return role;}public void setRole(AiMessageRole v){role=v;}public String getContent(){return content;}public void setContent(String v){content=v;}}
